/**
 * deployments.json -> apps/web/lib/deployments.ts
 *
 * Written by scripts/deploy-testnet.sh. The generated file is committed so a
 * fresh clone builds without a deploy, and regenerated on every deploy so the
 * two can never drift.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = new URL('..', import.meta.url).pathname;
const d = JSON.parse(readFileSync(join(root, 'deployments.json'), 'utf8'));

const out = `// GENERATED by scripts/write-deployments-module.mjs — do not edit.
// Source of truth: deployments.json at the repo root, written by
// scripts/deploy-testnet.sh. Regenerate with \`./scripts/deploy-testnet.sh\`.
//
// Deployed ${d.deployedAt}.

export const DEPLOYMENTS = {
  network: '${d.network}',
  networkPassphrase: '${d.networkPassphrase}',
  rpcUrl: '${d.rpcUrl}',
  /** Backend hot key: mints demo USDC, signs settle and refund. */
  resolver: '${d.accounts.resolver}',
  /** Where a settled order's USDC ends up. The app never signs for it. */
  treasury: '${d.accounts.treasury}',
  escrowId: '${d.contracts.escrow.id}',
  usdcId: '${d.contracts.usdc.id}',
  usdcDecimals: ${d.contracts.usdc.decimals},
} as const;
`;

writeFileSync(join(root, 'apps/web/lib/deployments.ts'), out);
console.log('  wrote apps/web/lib/deployments.ts');
